    const controls = new THREE.OrbitControls(camera, renderer.domElement);
    controls.enableDamping = true;
    controls.dampingFactor = 0.05;

    // Lighting
    const ambientLight = new THREE.AmbientLight(0xffffff, 0.5);
    scene.add(ambientLight);
    const directionalLight = new THREE.DirectionalLight(0xffffff, 0.8);
    directionalLight.position.set(1, 1, 1);
    scene.add(directionalLight);

    // UI Elements
    const ui = {
      money: document.getElementById('money-display'),
      payBtn: document.getElementById('pay-btn'),
      btnPress: document.getElementById('btn-press'),
      addSphere: document.getElementById('add-sphere'),
      removeSphere: document.getElementById('remove-sphere'),
      resetGrid: document.getElementById('reset-grid')
    };

    // Game state
    let spheres = [];
    let draggedSphere = null;
    let isDragging = false;
    let money = 0;
    let currentSphereCount = 32;
    let currentSphereSize = 0.5;
    let currentSpacing = 3.0;
    let currentGridLayout = 'square';
    let mouse = new THREE.Vector2();
    let raycaster = new THREE.Raycaster();

    // Initialize the game
    function init() {
      camera.position.z = 15;
      updateGrid();
      setupEventListeners();
      animate();
    }

    // Generate spheres in a grid
    function updateGrid() {
      // Clear existing spheres
      spheres.forEach(sphere => scene.remove(sphere));
      spheres = [];

      // Calculate grid dimensions
      let rows, cols;
      const count = Math.min(currentSphereCount, 256);
      switch (currentGridLayout) {
        case 'pi':
          rows = Math.floor(Math.sqrt(count / Math.PI));
          cols = Math.ceil(rows * Math.PI);
          break;
        case 'golden':
          const phi = (1 + Math.sqrt(5)) / 2;
          rows = Math.floor(Math.sqrt(count / phi));
          cols = Math.ceil(rows * phi);
          break;
        default: // square
          rows = Math.floor(Math.sqrt(count));
          cols = Math.ceil(count / rows);
