    #click-btn {
      background-color: #4CAF50;
      color: white;
    }
    #pay-btn {
      background-color: #ff9800;
      color: white;
    }
    #unlock-btn {
      background-color: #673AB7;
      color: white;
    }
    #upgrade-btn {
      background-color: #2196F3;
      color: white;
    }
    #reward {
      margin: 20px 0;
      font-size: 1.5rem;
      min-height: 50px;
      padding: 10px;
      border-radius: 10px;
      background: rgba(255, 255, 255, 0.7);
      display: none;
    }
