const ny = noise.simplex2(y _0.1, z_ 0.1) * 2 - 1;
const nz = noise.simplex2(z _0.1, x_ 0.1) * 2 - 1;
const position = new THREE.Vector3(
x - gridSize / 2 + nx,
y - gridSize / 2 + ny,
z - gridSize / 2 + nz
);
// Color based on noise
const color = new THREE.Color();
color.setHSL(
(noise.simplex2(x _0.2, y_ 0.2) + 1) / 2, // Hue (0-1)
0.7 + noise.simplex2(x _0.3, z_ 0.3) * 0.3, // Saturation
0.5 + noise.simplex2(y _0.4, z_ 0.4) * 0.5 // Lightness
);
const sphere = new THREE.Mesh(
new THREE.SphereGeometry(sphereRadius, 32, 32),
